package com.aether.launcher.ui

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.RectF
import android.graphics.Typeface
import android.os.Bundle
import android.view.MotionEvent
import android.view.View
import android.widget.Toast
import com.aether.launcher.settings.AetherSettingsActivity
import kotlin.math.abs

object AetherSurface { const val DRAWER="drawer";const val SEARCH="search";const val QUICK="quick";const val CONTROL="control";const val NOTIFICATIONS="notifications";const val WIDGETS="widgets";const val FOLDER="folder";const val MULTITASK="multitask";const val SETUP_CENTER="setup_center";const val ABOUT="about" }

class AetherSurfaceActivity : Activity(){ override fun onCreate(state:Bundle?){super.onCreate(state);setContentView(AetherSurfaceView(this,intent.getStringExtra("surface")?:AetherSurface.DRAWER,intent.getStringExtra("title")))} }

class AetherSurfaceView(context:Context,private val surface:String,private val incomingTitle:String?):View(context){
 private val p=Paint(Paint.ANTI_ALIAS_FLAG);private var downX=0f;private var downY=0f;private val apps get()=com.aether.launcher.AetherRuntime.registry.launcher.apps()
 init{p.typeface=Typeface.DEFAULT}
 override fun onDraw(c:Canvas){val w=width.toFloat();val h=height.toFloat();p.color=0xFF080A0E.toInt();c.drawRect(0f,0f,w,h,p);p.color=0x162A3440;c.drawCircle(w*.12f,h*.18f,w*.38f,p);p.color=0x121D3B32;c.drawCircle(w*.88f,h*.72f,w*.44f,p);p.color=Color.WHITE;p.textAlign=Paint.Align.LEFT;p.textSize=28f;p.typeface=Typeface.DEFAULT_BOLD;c.drawText(title(),24f,52f,p);p.color=0x88FFFFFF.toInt();p.textSize=12f;c.drawText("Aether surface",24f,74f,p);when(surface){AetherSurface.DRAWER->drawer(c,w,h);AetherSurface.SEARCH->search(c,w,h);AetherSurface.QUICK->quick(c,w,h);AetherSurface.CONTROL->control(c,w,h);AetherSurface.NOTIFICATIONS->notifications(c,w,h);AetherSurface.WIDGETS->widgets(c,w,h);AetherSurface.FOLDER->folder(c,w,h);AetherSurface.MULTITASK->multitask(c,w,h);AetherSurface.SETUP_CENTER->setupCenter(c,w,h);else->about(c,w,h)}}
 private fun title()=when(surface){AetherSurface.DRAWER->"App Drawer";AetherSurface.SEARCH->"Search";AetherSurface.QUICK->"Quick Space";AetherSurface.CONTROL->"Control Center";AetherSurface.NOTIFICATIONS->"Notifications";AetherSurface.WIDGETS->"Widgets";AetherSurface.FOLDER->incomingTitle?.ifBlank{"Folder"}?:"Folder";AetherSurface.MULTITASK->"Aether Multitask";AetherSurface.SETUP_CENTER->"Setup Center";else->"About Aether"}
 private fun panel(c:Canvas,w:Float,h:Float,top:Float=92f,bottom:Float=.92f){p.color=0xE8171A20.toInt();c.drawRoundRect(RectF(w*.05f,top,w*.95f,h*bottom),32f,32f,p);p.color=0x26FFFFFF;c.drawRoundRect(RectF(w*.05f+2,top+2,w*.95f-2,h*bottom-2),32f,32f,p)}
 private fun drawer(c:Canvas,w:Float,h:Float){panel(c,w,h);p.color=0x25FFFFFF;c.drawRoundRect(RectF(20f,104f,w-20f,158f),27f,27f,p);p.color=Color.WHITE;p.textSize=14f;c.drawText("⌕  Search apps",40f,138f,p);val cols=4;val cell=(w-52f)/4f;apps.forEachIndexed{i,a->{if(i>=40)return@forEachIndexed;val col=i%cols;val row=i/cols;val x=20f+col*(cell+4f);val y=176f+row*88f;p.color=0x451C222A;c.drawRoundRect(RectF(x,y,x+cell-4f,y+62f),20f,20f,p);p.color=Color.WHITE;p.textAlign=Paint.Align.CENTER;p.textSize=10f;c.drawText(a.label.take(11),x+(cell-4f)/2,y+78f,p);p.textAlign=Paint.Align.LEFT}}}
 private fun search(c:Canvas,w:Float,h:Float){panel(c,w,h);p.color=0x25FFFFFF;c.drawRoundRect(RectF(20f,104f,w-20f,158f),27f,27f,p);p.color=Color.WHITE;p.textSize=15f;c.drawText("⌕  Search apps",40f,138f,p);apps.take(8).forEachIndexed{i,a->{p.color=0x28FFFFFF;c.drawRoundRect(RectF(24f,174f+i*70f,w-24f,230f+i*70f),20f,20f,p);p.color=Color.WHITE;p.textSize=14f;c.drawText(a.label,44f,208f+i*70f,p)}}}
 private fun quick(c:Canvas,w:Float,h:Float){panel(c,w,h,.18f,.91f);val labels=listOf("Notes","Voice","Calculator","Screenshot","Clipboard","Recent","Shortcuts","Settings");labels.forEachIndexed{i,l->{val x=w*.09f+(i%2)*w*.43f;val y=h*.27f+(i/2)*82f;p.color=0x35FFFFFF;c.drawRoundRect(RectF(x,y,x+w*.38f,y+62f),22f,22f,p);p.color=Color.WHITE;p.textAlign=Paint.Align.CENTER;p.textSize=13f;c.drawText(l,x+w*.19f,y+38f,p);p.textAlign=Paint.Align.LEFT}}}
 private fun control(c:Canvas,w:Float,h:Float){panel(c,w,h);val labels=listOf("Wi-Fi","Bluetooth","Airplane","Rotation","Flashlight","Focus","Brightness","Volume");labels.forEachIndexed{i,l->{val x=w*.09f+(i%2)*w*.43f;val y=140f+(i/2)*86f;p.color=0x30FFFFFF;c.drawRoundRect(RectF(x,y,x+w*.38f,y+66f),24f,24f,p);p.color=Color.WHITE;p.textAlign=Paint.Align.CENTER;p.textSize=13f;c.drawText(l,x+w*.19f,y+40f,p);p.textAlign=Paint.Align.LEFT}}}
 private fun notifications(c:Canvas,w:Float,h:Float){panel(c,w,h);p.color=Color.WHITE;p.textSize=14f;c.drawText("Notification Center",40f,140f,p);p.color=0xAAFFFFFF.toInt();p.textSize=12f;c.drawText("Live notifications will appear here when Notification Access is enabled.",40f,168f,p);c.drawText("Dynamic Island can mirror important activities above.",40f,190f,p)}
 private fun widgets(c:Canvas,w:Float,h:Float){panel(c,w,h);val labels=listOf("Clock","Weather","Calendar","Notes","Battery","Quick Actions");labels.forEachIndexed{i,l->{val x=22f+(i%2)*(w*.46f);val y=126f+(i/2)*106f;p.color=0x30FFFFFF;c.drawRoundRect(RectF(x,y,x+w*.42f,y+88f),24f,24f,p);p.color=Color.WHITE;p.textAlign=Paint.Align.CENTER;p.textSize=13f;c.drawText(l,x+w*.21f,y+50f,p);p.textAlign=Paint.Align.LEFT}}}
 private fun folder(c:Canvas,w:Float,h:Float){panel(c,w,h);p.color=Color.WHITE;p.textSize=14f;c.drawText("Arrange apps",40f,130f,p);apps.take(12).forEachIndexed{i,a->{val x=30f+(i%3)*w*.30f;val y=158f+(i/3)*92f;p.color=0x35FFFFFF;c.drawRoundRect(RectF(x,y,x+w*.25f,y+66f),20f,20f,p);p.color=Color.WHITE;p.textAlign=Paint.Align.CENTER;p.textSize=10f;c.drawText(a.label.take(10),x+w*.125f,y+40f,p);p.textAlign=Paint.Align.LEFT}}}
 private fun multitask(c:Canvas,w:Float,h:Float){panel(c,w,h);val labels=listOf("Floating window","Split 50 / 50","Split 60 / 40","Snap left","Snap right","Mini window");labels.forEachIndexed{i,l->{val y=118f+i*78f;p.color=0x30FFFFFF;c.drawRoundRect(RectF(22f,y,w-22f,y+60f),22f,22f,p);p.color=Color.WHITE;p.textSize=14f;c.drawText(l,42f,y+28f,p);p.color=0x88FFFFFF.toInt();p.textSize=11f;c.drawText("Configure in Aether Settings",42f,y+47f,p)}}}
 private fun setupCenter(c:Canvas,w:Float,h:Float){panel(c,w,h);val labels=listOf("Default launcher","Draw over other apps","Notification access","Accessibility","Shizuku","Battery optimization");labels.forEachIndexed{i,l->{val y=116f+i*76f;p.color=0x30FFFFFF;c.drawRoundRect(RectF(20f,y,w-20f,y+60f),22f,22f,p);p.color=Color.WHITE;p.textSize=14f;c.drawText(l,40f,y+28f,p);p.color=0x88FFFFFF.toInt();p.textSize=11f;c.drawText("Open system settings",40f,y+46f,p)}}}
 private fun about(c:Canvas,w:Float,h:Float){panel(c,w,h,.18f,.84f);p.color=Color.WHITE;p.textAlign=Paint.Align.CENTER;p.textSize=60f;c.drawText("A",w/2,230f,p);p.textSize=18f;c.drawText("AETHER",w/2,266f,p);p.color=0xAAFFFFFF.toInt();p.textSize=13f;c.drawText("Liquid interaction • Dynamic Island • Quick Space",w/2,302f,p);c.drawText("UI prototype • Engine architecture in progress",w/2,326f,p);p.textAlign=Paint.Align.LEFT}
 override fun onTouchEvent(e:MotionEvent):Boolean{if(e.action==MotionEvent.ACTION_DOWN){downX=e.x;downY=e.y;return true};if(e.action==MotionEvent.ACTION_UP){val dx=e.x-downX;val dy=e.y-downY;if(surface==AetherSurface.DRAWER&&downY>100&&downY<165){start(AetherSurface.SEARCH);return true};if(surface==AetherSurface.DRAWER&&downY>170){val cell=width/4f;val col=(e.x/cell).toInt();val row=((e.y-176f)/88f).toInt();val i=row*4+col;if(i in apps.indices)context.packageManager.getLaunchIntentForPackage(apps[i].packageName)?.let{context.startActivity(it)};return true};if(surface==AetherSurface.QUICK&&downY>height*.25f&&downY<height*.75f){val i=((downY-height*.27f)/82f).toInt()*2+(if(e.x<width/2)0 else 1);if(i==7)context.startActivity(Intent(context,AetherSettingsActivity::class.java));else Toast.makeText(context,"Aether action",Toast.LENGTH_SHORT).show();return true};if(surface==AetherSurface.MULTITASK||surface==AetherSurface.SETUP_CENTER){Toast.makeText(context,"Aether action selected",Toast.LENGTH_SHORT).show();return true};if(abs(dx)>70||abs(dy)>70){(context as? Activity)?.finish();return true}};return true}
 private fun start(s:String){context.startActivity(Intent(context,AetherSurfaceActivity::class.java).putExtra("surface",s))}
}
